 // Example input: {\"tree\":[3,1,4,null,2],\"k\":1}\n  // Expected: 1\n  return null;\n}", "solution": "function solve(input) {\nfunction build(a){if(!a.length||a[0]===null)return null;const root={val:a[0],left:null,right:null},q=[root];let i=1,h=0;while(i<a.length&&h<q.length){const p=q[h++];for(const key of [\"left\",\"right\"]){if(i<a.length&&a[i]!==null){p[key]={val:a[i],left:null,right:null};q.push(p[key])}i++}}return root}const root=build(input.tree);let k=input.k,p=root;const s=[];while(p||s.length){while(p){s.push(p);p=p.left}p=s.pop();if(--k===0)return p.val;p=p.right}return null;\n}", "tests": [{"input": {"tree": [3, 1, 4, null, 2], "k": 1}, "expected": 1}, {"input": {"tree": [3, 1, 4, null, 2], "k": 4}, "expected": 4}], "link": "https://leetcode.com/problemset/", "solutions": {"python": "def solve(input):\n    class Node:\n        def __init__(self,val): self.val=val;self.left=None;self.right=None\n    def build(a):\n        if not a or a[0] is None: return None\n        root=Node(a[0]);q=[root];i=1;h=0\n        while i<len(a) and h<len(q):\n            p=q[h];h+=1\n            for key in (\"left\",\"right\"):\n                if i<len(a) and a[i] is not None:\n                    n=Node(a[i]);setattr(p,key,n);q.append(n)\n                i+=1\n        return root\n    p=build(input[\"tree\"]);s=[];k=input[\"k\"]\n    while p or s:\n        while p: s.append(p);p=p.left\n        p=s.pop();k-=1\n        if k==0: return p.val\n        p=p.right\n", "cpp": "json solve(const json& input) {\nstruct Node{int val;Node*left=nullptr;Node*right=nullptr;Node(int x):val(x){}};vector<unique_ptr<Node>>pool;auto make=[&](int x){pool.push_back(make_unique<Node>(x));return pool.back().get();};auto build=[&](const json&a)->Node*{if(a.empty()||a[0].is_null())return nullptr;Node*root=make(a[0].get<int>());vector<Node*>q{root};int i=1,h=0;while(i<(int)a.size()&&h<(int)q.size()){Node*p=q[h++];if(i<(int)a.size()&&!a[i].is_null()){p->left=make(a[i].get<int>());q.push_back(p->le